from langchain.text_splitter import RecursiveCharacterTextSplitter
from langchain_community.vectorstores import Chroma
from langchain_community.document_loaders import PyPDFLoader
from langchain.chains import RetrievalQA
from langchain_community.embeddings import HuggingFaceEmbeddings
from langchain_community.llms import Ollama

import gradio as gr
import os
from dotenv import load_dotenv

# Load environment variables from .env file
load_dotenv()

# You can use this section to suppress warnings generated by your code:
def warn(*args, **kwargs):
    pass
import warnings
warnings.warn = warn
warnings.filterwarnings('ignore')


## LLM
def get_llm():
    # Using Ollama with Qwen 4B (lightweight, optimized for non-advanced computers)
    llm = Ollama(
        model="qwen:4b",
        base_url="http://localhost:11434",
        temperature=0.5,
    )
    return llm


## Document loader
def document_loader(file):
    # Gradio passes a file path string (type="filepath"); older versions pass an object with .name
    path = file if isinstance(file, str) else file.name
    loader = PyPDFLoader(path)
    loaded_document = loader.load()
    return loaded_document


## Text splitter
def text_splitter(data):
    text_splitter = RecursiveCharacterTextSplitter(
        chunk_size=1000,
        chunk_overlap=50,
        length_function=len,
    )
    chunks = text_splitter.split_documents(data)
    return chunks


## Vector db
def vector_database(chunks):
    embedding_model = get_embeddings()
    vectordb = Chroma.from_documents(chunks, embedding_model)
    return vectordb

## Embedding model
def get_embeddings():
    # Using HuggingFace embeddings (free, open-source)
    embeddings = HuggingFaceEmbeddings(
        model_name="sentence-transformers/all-MiniLM-L6-v2"
    )
    return embeddings

## Retriever
def retriever(file):
    splits = document_loader(file)
    chunks = text_splitter(splits)
    vectordb = vector_database(chunks)
    retriever = vectordb.as_retriever()
    return retriever

## QA Chain
def retriever_qa(file, query):
    llm = get_llm()
    retriever_obj = retriever(file)
    qa = RetrievalQA.from_chain_type(llm=llm, 
                                    chain_type="stuff", 
                                    retriever=retriever_obj, 
                                    return_source_documents=False)
    response = qa.invoke(query)
    return response['result']

# Create Gradio interface with improved UI
with gr.Blocks(title="RAG Chatbot - Powered by Qwen 4B", theme=gr.themes.Soft()) as rag_application:
    gr.HTML("""
    <div style="text-align: center; margin-bottom: 20px;">
        <h1 style="color: #2563eb; font-size: 2.5em; margin-bottom: 10px;">📚 RAG Chatbot</h1>
        <p style="color: #6b7280; font-size: 1.1em; margin-bottom: 5px;">Ask questions about your documents using AI</p>
        <p style="color: #9ca3af; font-size: 0.9em;">Powered by Qwen 4B • Local AI • No API Keys Required</p>
    </div>
    """)

    with gr.Row():
        with gr.Column(scale=1):
            gr.HTML("""
            <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 20px; border-radius: 10px; margin-bottom: 20px;">
                <h3 style="margin: 0 0 10px 0;">🚀 How to Use</h3>
                <ol style="margin: 0; padding-left: 20px;">
                    <li>Upload a PDF document</li>
                    <li>Ask questions about its content</li>
                    <li>Get AI-powered answers instantly</li>
                </ol>
            </div>
            """)

            file_input = gr.File(
                label="📄 Upload PDF Document",
                file_count="single",
                file_types=['.pdf'],
                type="filepath",
                height=100
            )

            with gr.Accordion("💡 Example Questions", open=False):
                gr.Examples(
                    examples=[
                        "What is the main topic of this document?",
                        "Summarize the key points",
                        "What are the main conclusions?",
                        "Explain the methodology used",
                        "What are the recommendations?"
                    ],
                    inputs=gr.Textbox(label="Example Query", placeholder="Click an example to try it...")
                )

        with gr.Column(scale=2):
            query_input = gr.Textbox(
                label="❓ Ask Your Question",
                lines=3,
                placeholder="Type your question about the uploaded document here..."
            )

            submit_btn = gr.Button(
                "🔍 Ask Question",
                variant="primary",
                size="lg"
            )

            output = gr.Textbox(
                label="🤖 AI Response",
                lines=8,
                interactive=False
            )

            with gr.Accordion("📊 Processing Status", open=False):
                status = gr.Textbox(
                    label="Status",
                    value="Ready to process your document...",
                    interactive=False,
                    lines=2
                )

    # Event handling
    def update_status(message):
        return message

    def process_query(file, query):
        if not file:
            return "❌ Please upload a PDF file first!", "❌ Error: No file uploaded"
        if not query.strip():
            return "❌ Please enter a question!", "❌ Error: Empty question"

        try:
            status_msg = "🔄 Processing document and generating answer..."
            yield "", status_msg

            result = retriever_qa(file, query.strip())
            status_msg = "✅ Answer generated successfully!"
            yield result, status_msg
        except Exception as e:
            error_msg = f"❌ Error: {str(e)}"
            yield error_msg, "❌ Processing failed"

    submit_btn.click(
        fn=process_query,
        inputs=[file_input, query_input],
        outputs=[output, status],
        api_name="ask_question"
    )

    gr.HTML("""
    <div style="text-align: center; margin-top: 30px; padding: 20px; background: #f8fafc; border-radius: 10px;">
        <p style="color: #6b7280; margin: 0;">
            <strong>Supported:</strong> PDF documents • <strong>Model:</strong> Qwen 4B (Local) •
            <strong>Privacy:</strong> All processing happens locally on your computer
        </p>
    </div>
    """)


# Launch the app
rag_application.launch(
    server_name="localhost",
    server_port=7863,
    show_error=True,
    share=False
)